<?php
require 'db.php'; session_start(); require 'includes.php';
if (($_SESSION['user_role'] ?? '') !== 'admin') { header('Location: login.php'); exit; }
ob_start(static function (string $page): string {
    $page = preg_replace('~<title>.*?</title>~', '<title>Hostel Admin Dashboard | StaySpace</title>', $page, 1);
    return str_replace(
        ['Operations dashboard', 'Manage student requests and hostel capacity.'],
        ['Hostel Admin Dashboard', 'Manage students, room requests, room inventory, and hostel operations from one place.'],
        $page
    );
});
if (isset($_GET['action'],$_GET['id']) && in_array($_GET['action'],['approve','reject'],true)) { $id=(int)$_GET['id']; $conn->begin_transaction(); try { $q=$conn->prepare('SELECT room_id,status FROM room_requests WHERE id=? FOR UPDATE');$q->bind_param('i',$id);$q->execute();$r=$q->get_result()->fetch_assoc();if(!$r||$r['status']!=='Pending')throw new Exception('This request has already been processed.'); if($_GET['action']==='approve'){$q=$conn->prepare("UPDATE room_requests SET status='Approved', payment_status='Unpaid' WHERE id=?");$q->bind_param('i',$id);$q->execute();flash('success','Request approved. Payment is now due.');}else{$q=$conn->prepare("UPDATE room_requests SET status='Rejected' WHERE id=?");$q->bind_param('i',$id);$q->execute();$q=$conn->prepare("UPDATE rooms SET available_beds=LEAST(total_beds,available_beds+1), room_status=CASE WHEN room_status='Maintenance' THEN 'Maintenance' ELSE 'Available' END WHERE id=?");$q->bind_param('i',$r['room_id']);$q->execute();flash('success','Request rejected and the bed was released.');}$conn->commit();}catch(Throwable $e){$conn->rollback();flash('error',$e->getMessage());} header('Location: admin_dashboard.php');exit; }
if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['set_payment'])) { $id=(int)($_POST['request_id']??0); $payment=$_POST['payment_status']??''; if(!in_array($payment,['Paid','Unpaid'],true)) { flash('error','Invalid payment status.'); } else { $q=$conn->prepare("UPDATE room_requests SET payment_status=? WHERE id=? AND status='Approved'"); $q->bind_param('si',$payment,$id); $q->execute(); flash($q->affected_rows?'success':'error',$q->affected_rows?'Payment status updated.':'Only approved requests can have payment updated.'); $q->close(); } header('Location: admin_dashboard.php'); exit; }
$students=$conn->query("SELECT COUNT(*) c FROM users WHERE role='student'")->fetch_assoc()['c'];$totalRooms=$conn->query('SELECT COUNT(*) c FROM rooms')->fetch_assoc()['c'];$occupied=$conn->query('SELECT COALESCE(SUM(available_beds),0) c FROM rooms')->fetch_assoc()['c'];$availableRooms=$conn->query("SELECT COUNT(*) c FROM rooms WHERE available_beds>0 AND room_status='Available'")->fetch_assoc()['c'];$occupiedRooms=$conn->query("SELECT COUNT(*) c FROM rooms WHERE available_beds=0 OR room_status='Full'")->fetch_assoc()['c'];$pending=$conn->query("SELECT COUNT(*) c FROM room_requests WHERE status='Pending'")->fetch_assoc()['c'];$approved=$conn->query("SELECT COUNT(*) c FROM room_requests WHERE status='Approved'")->fetch_assoc()['c'];$revenue=$conn->query("SELECT COALESCE(SUM(final_amount),0) v FROM room_requests WHERE payment_status='Paid'")->fetch_assoc()['v'];
$requestFilter=$_GET['status']??'';$search=trim($_GET['q']??'');$where='';if(in_array($requestFilter,['Pending','Approved','Rejected'],true))$where="WHERE req.status='".$conn->real_escape_string($requestFilter)."'";if($search!=='')$where.=($where?' AND ':'WHERE ')."(u.name LIKE '%".$conn->real_escape_string($search)."%' OR r.room_number LIKE '%".$conn->real_escape_string($search)."%' OR req.roll_no LIKE '%".$conn->real_escape_string($search)."%')";
$requests=$conn->query("SELECT req.*,u.name,u.email,u.branch,r.room_number,r.room_type FROM room_requests req JOIN users u ON u.id=req.user_id JOIN rooms r ON r.id=req.room_id $where ORDER BY req.created_at DESC LIMIT 15");$rooms=$conn->query('SELECT * FROM rooms ORDER BY room_number');$roomChart=$conn->query('SELECT room_number,available_beds FROM rooms ORDER BY room_number');$labels=[];$beds=[];while($chart=$roomChart->fetch_assoc()){$labels[]=$chart['room_number'];$beds[]=(int)$chart['available_beds'];}$recentStudents=$conn->query("SELECT name,email,branch,created_at FROM users WHERE role='student' ORDER BY created_at DESC LIMIT 5");$flash=consume_flash();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Control · StaySpace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/app.css"><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><script src="https://cdn.jsdelivr.net/npm/chart.js"></script></head><body><div class="app"><aside class="sidebar"><div class="brand"><i class="fa-solid fa-building-shield"></i><span>StaySpace</span></div><div class="nav-label">ADMIN CONTROL</div><nav class="nav"><a class="active" href="#overview"><i class="fa-solid fa-chart-pie"></i><span>Dashboard</span></a><a href="#requests"><i class="fa-solid fa-clipboard-check"></i><span>Room requests</span></a><a href="#rooms"><i class="fa-solid fa-bed"></i><span>Room inventory</span></a><a href="export_requests.php"><i class="fa-solid fa-file-pdf"></i><span>Export requests</span></a><a class="logout" href="logout.php"><i class="fa-solid fa-arrow-right-from-bracket"></i><span>Sign out</span></a></nav></aside><main class="content"><header class="topbar"><div><h1>Operations dashboard</h1><p class="eyebrow">Manage student requests and hostel capacity.</p></div><div class="top-actions"><button class="icon-btn" data-theme-toggle><i class="fa-solid fa-moon"></i></button><div class="avatar" style="display:grid;place-items:center;background:#eef2ff;color:#4f46e5"><i class="fa-solid fa-user-shield"></i></div><span class="name">Hostel Admin</span></div></header>
<section id="overview" class="stats"><div class="stat-card"><i class="stat-icon fa-solid fa-users"></i><div class="stat-label">Registered students</div><div class="stat-number"><?=$students?></div></div><div class="stat-card"><i class="stat-icon fa-solid fa-clock"></i><div class="stat-label">Pending review</div><div class="stat-number"><?=$pending?></div></div><div class="stat-card"><i class="stat-icon fa-solid fa-bed"></i><div class="stat-label">Available beds</div><div class="stat-number"><?=$occupied?></div></div><div class="stat-card"><i class="stat-icon fa-solid fa-indian-rupee-sign"></i><div class="stat-label">Revenue collected</div><div class="stat-number">₹<?=number_format($revenue)?></div></div></section>
<section class="stats stats-six"><div class="stat-card"><div class="stat-label">Total Students</div><div class="stat-number"><?=$students?></div></div><div class="stat-card"><div class="stat-label">Total Rooms</div><div class="stat-number"><?=$totalRooms?></div></div><div class="stat-card"><div class="stat-label">Available Rooms</div><div class="stat-number"><?=$availableRooms?></div></div><div class="stat-card"><div class="stat-label">Occupied Rooms</div><div class="stat-number"><?=$occupiedRooms?></div></div><div class="stat-card"><div class="stat-label">Pending Requests</div><div class="stat-number"><?=$pending?></div></div><div class="stat-card"><div class="stat-label">Approved Requests</div><div class="stat-number"><?=$approved?></div></div></section>
<div class="grid-2"><section class="card"><div class="card-heading"><h2>Availability by room</h2></div><canvas id="occupancy" height="155"></canvas></section><section class="card"><div class="card-heading"><h2>Quick actions</h2></div><p class="muted">Review pending applications and keep room availability accurate.</p><p><a class="btn btn-primary" href="#requests"><i class="fa-solid fa-clipboard-check"></i> Review requests</a></p><p><a class="btn btn-light" href="admin_rooms.php"><i class="fa-solid fa-bed"></i> Manage rooms</a> <a class="btn btn-light" href="admin_students.php"><i class="fa-solid fa-users"></i> Manage students</a></p><p><a class="btn btn-light" href="export_requests.php"><i class="fa-solid fa-file-export"></i> Export to PDF</a></p><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><h2 style="font-size:15px">Recent students</h2><?php while($s=$recentStudents->fetch_assoc()):?><p style="margin:12px 0"><strong><?=e($s['name'])?></strong><br><small class="muted"><?=e($s['branch']?:$s['email'])?></small></p><?php endwhile;?></section></div>
<section id="requests" class="card"><div class="card-heading"><h2>Recent room requests</h2><a class="btn btn-light" href="export_requests.php">Export PDF</a></div><form class="toolbar" method="get"><input class="field" name="q" value="<?=e($search)?>" placeholder="Search name, roll number or room"><select name="status"><option value="">All statuses</option><?php foreach(['Pending','Approved','Rejected'] as $st):?><option <?=$requestFilter===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><button class="btn btn-primary">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Student</th><th>Room</th><th>Plan</th><th>Amount</th><th>Request status</th><th>Payment</th><th>Action</th></tr></thead><tbody><?php if($requests->num_rows===0):?><tr><td colspan="7" class="empty">No matching room requests.</td></tr><?php else:while($r=$requests->fetch_assoc()):?><tr><td><strong><?=e($r['name'])?></strong><br><small class="muted"><?=e($r['roll_no'])?> · <?=e($r['branch'])?></small></td><td><?=e($r['room_number'])?><br><small class="muted"><?=e($r['room_type'])?></small></td><td><?=e($r['stay_duration'])?></td><td>₹<?=number_format($r['final_amount'])?></td><td><span class="badge <?=status_class($r['status'])?>"><?=e($r['status'])?></span></td><td><?php if($r['status']==='Approved'):?><form method="post"><input type="hidden" name="request_id" value="<?=$r['id']?>"><select name="payment_status" onchange="this.form.submit()"><option value="Unpaid" <?=$r['payment_status']==='Unpaid'?'selected':''?>>Due</option><option value="Paid" <?=$r['payment_status']==='Paid'?'selected':''?>>Paid</option></select><input type="hidden" name="set_payment" value="1"></form><?php else:?><span class="badge unpaid">Due</span><?php endif;?></td><td><?php if($r['status']==='Pending'):?><a class="btn btn-primary" href="admin_dashboard.php?action=approve&id=<?=$r['id']?>" data-confirm="Approve this request? Payment will remain due until you mark it paid.">Approve</a> <a class="btn btn-danger" href="admin_dashboard.php?action=reject&id=<?=$r['id']?>" data-confirm="Reject this request and release the reserved bed?">Reject</a><?php else:?><span class="muted">Processed</span><?php endif;?></td></tr><?php endwhile;endif;?></tbody></table></div></section>
<section id="rooms" class="card"><div class="card-heading"><h2>Room inventory</h2><span class="muted">Live availability</span></div><div class="room-grid"><?php while($room=$rooms->fetch_assoc()):$full=$room['available_beds']<1;?><article class="card room"><img src="<?=e(room_image($room))?>" alt="Room"><div class="room-body"><span class="badge <?=$full?'full':'available'?>"><?=$full?'Full':'Available'?></span><h3 class="room-title" style="margin-top:12px">Room <?=e($room['room_number'])?></h3><p class="muted"><?=e($room['room_type'])?> · <?=e($room['location'])?></p><div class="room-meta"><span><?=$room['available_beds']?> beds free</span><strong>₹<?=number_format($room['fees_per_sem'])?></strong></div></div></article><?php endwhile;?></div></section></main></div><?php if($flash):?><div id="flash" data-type="<?=e($flash['type'])?>" data-message="<?=e($flash['text'])?>"></div><?php endif;?><script src="assets/js/app.js"></script><script>new Chart(document.getElementById('occupancy'),{type:'bar',data:{labels:<?=json_encode($labels)?>,datasets:[{label:'Available beds',data:<?=json_encode($beds)?>,backgroundColor:'#6366f1',borderRadius:8}]},options:{plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});const f=document.getElementById('flash');if(f)Swal.fire({toast:true,position:'top-end',showConfirmButton:false,timer:3500,icon:f.dataset.type==='success'?'success':'error',title:f.dataset.message});</script></body></html>
